import express, { Express } from 'express';
import { AdvanceOrderUseCase } from '../application/AdvanceOrderUseCase';
import { CancelOrderUseCase } from '../application/CancelOrderUseCase';
import { GetOrderUseCase } from '../application/GetOrderUseCase';
import { ListOrdersUseCase } from '../application/ListOrdersUseCase';
import { ListStockLevelsUseCase } from '../application/ListStockLevelsUseCase';
import { PlaceOrderUseCase } from '../application/PlaceOrderUseCase';
import { StockReservationService } from '../domain/StockReservationService';
import { seedCatalogue } from './catalogueSeed';
import { errorHandler, notFoundHandler } from './errorHandler';
import { InMemoryOrderRepository } from './InMemoryOrderRepository';
import { InMemoryProductRepository } from './InMemoryProductRepository';
import { OrderController } from './OrderController';
import { StockController } from './StockController';
import { SystemClock } from './SystemClock';
import { UuidIdGenerator } from './UuidIdGenerator';

/** Composition root: wires implementations to abstractions and builds the Express app. */
export function createApp(): Express {
  const products = new InMemoryProductRepository();
  const orders = new InMemoryOrderRepository();
  seedCatalogue(products);

  const clock = new SystemClock();
  const stock = new StockReservationService(products);

  const orderController = new OrderController({
    placeOrder: new PlaceOrderUseCase(orders, stock, new UuidIdGenerator(), clock),
    advanceOrder: new AdvanceOrderUseCase(orders, stock, clock),
    cancelOrder: new CancelOrderUseCase(orders, stock, clock),
    getOrder: new GetOrderUseCase(orders),
    listOrders: new ListOrdersUseCase(orders),
  });
  const stockController = new StockController(new ListStockLevelsUseCase(products));

  const app = express();
  app.use(express.json());
  app.use('/orders', orderController.router());
  app.use('/stock', stockController.router());
  app.use(notFoundHandler);
  app.use(errorHandler);
  return app;
}

