import { NextFunction, Request, Response } from 'express';
import {
  DomainError,
  InsufficientStockError,
  InvalidStateTransitionError,
  NotFoundError,
  ValidationError,
} from '../domain/errors';

function statusFor(error: DomainError): number {
  if (error instanceof ValidationError) return 400;
  if (error instanceof NotFoundError) return 404;
  if (error instanceof InsufficientStockError || error instanceof InvalidStateTransitionError) return 409;
  return 422;
}

/** Body-parser failures carry an HTTP status in the 4xx range. */
function clientStatusOf(error: unknown): number | undefined {
  if (typeof error !== 'object' || error === null || !('status' in error)) return undefined;
  const status = (error as { status: unknown }).status;
  return typeof status === 'number' && status >= 400 && status < 500 ? status : undefined;
}

export function notFoundHandler(req: Request, res: Response): void {
  res.status(404).json({ error: 'NotFound', message: `No route for ${req.method} ${req.path}` });
}

export function errorHandler(error: unknown, _req: Request, res: Response, _next: NextFunction): void {
  if (error instanceof DomainError) {
    res.status(statusFor(error)).json({ error: error.name, message: error.message });
    return;
  }
  const clientStatus = clientStatusOf(error);
  if (clientStatus !== undefined) {
    res.status(clientStatus).json({ error: 'BadRequest', message: 'Malformed request' });
    return;
  }
  console.error(error);
  res.status(500).json({ error: 'InternalServerError', message: 'Unexpected error' });
}

