import { PlaceOrderInput } from '../application/dtos';
import { ValidationError } from '../domain/errors';
import { OrderStatus, isOrderStatus } from '../domain/OrderStatus';

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Checks the HTTP body shape; business rules are enforced by the domain. */
export function parsePlaceOrderBody(body: unknown): PlaceOrderInput {
  if (!isRecord(body)) throw new ValidationError('Request body must be a JSON object');

  const { customerId, lines } = body;
  if (typeof customerId !== 'string') throw new ValidationError('customerId must be a string');
  if (!Array.isArray(lines)) throw new ValidationError('lines must be an array');

  return {
    customerId,
    lines: lines.map((line: unknown, index) => {
      if (!isRecord(line)) throw new ValidationError(`lines[${index}] must be an object`);
      const { productId, quantity } = line;
      if (typeof productId !== 'string') throw new ValidationError(`lines[${index}].productId must be a string`);
      if (typeof quantity !== 'number') throw new ValidationError(`lines[${index}].quantity must be a number`);
      return { productId, quantity };
    }),
  };
}

export function parseStatusQuery(value: unknown): OrderStatus | undefined {
  if (value === undefined) return undefined;
  if (!isOrderStatus(value)) throw new ValidationError(`Unknown order status '${String(value)}'`);
  return value;
}

